method digitSum(s: string) returns (sum: int)
    // Precondition: s is a valid string
    requires s != null
    // Postcondition: sum is the sum of ASCII values of uppercase characters in s
    ensures sum == (if s == "" then 0 else 
                    sum(i | i in 0 .. s.Length && 'A' <= s[i] && s[i] <= 'Z' | s[i].Ascii()));
{
    sum := 0;
    var i := 0;
    while i < s.Length
        // Invariant: sum is the sum of ASCII values of uppercase characters in s[0..i)
        invariant 0 <= i <= s.Length
        invariant sum == (if i == 0 then 0 else 
                          sum(j | j in 0 .. i && 'A' <= s[j] && s[j] <= 'Z' | s[j].Ascii()));
    {
        if 'A' <= s[i] && s[i] <= 'Z' {
            sum := sum + s[i].Ascii();
        }
        i := i + 1;
    }
}
